import{_ as d,C as o,o as n,c as s,a3 as r,E as e}from"./chunks/framework.CZBGEXos.js";const m=JSON.parse('{"title":"Terminal","description":"","frontmatter":{},"headers":[],"relativePath":"ru/tools/terminal.md","filePath":"ru/tools/terminal.md"}'),i={name:"ru/tools/terminal.md"};function l(h,t,b,p,c,g){const a=o("Screenshot");return n(),s("div",null,[t[0]||(t[0]=r('<h1 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal&quot;">​</a></h1><p>Terminal — это торговый терминал с глубиной рынка. Это единственный инструмент Sentaro, который не является монитором: он подключается к биржевому аккаунту по предоставленным вами ключам и выставляет, отменяет и закрывает реальные ордера реальными средствами.</p><p>Он работает с пятью площадками на трёх биржах:</p><table tabindex="0"><thead><tr><th>Площадка</th><th>Биржа</th><th>Рынок</th></tr></thead><tbody><tr><td>Hyperliquid</td><td>Hyperliquid</td><td>Бессрочные контракты</td></tr><tr><td>Binance Perp</td><td>Binance</td><td>Бессрочные фьючерсы</td></tr><tr><td>Binance Spot</td><td>Binance</td><td>Спот</td></tr><tr><td>Bybit Perp</td><td>Bybit</td><td>Бессрочные фьючерсы</td></tr><tr><td>Bybit Spot</td><td>Bybit</td><td>Спот</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Это незавершённый proof of concept</p><p>Terminal — тестовый инструмент, а не основной продукт. В нём есть ошибки, он не является приоритетом разработки и может вести себя непредсказуемо. Поддержка Binance и Bybit новее, чем Hyperliquid, и соответственно менее проверена.</p><p>Он также торгует реальными деньгами:</p><ul><li><strong>Никакого подтверждения нет.</strong> Один клик по лестнице цен мгновенно отправляет ордер. Нет ни «вы уверены?», ни предпросмотра, ни отмены.</li><li><strong>Нужны торговые ключи</strong> — приватный ключ подписанта на Hyperliquid, API-ключ и секрет с разрешением на торговлю на Binance и Bybit.</li><li><strong>Убытки реальны и необратимы.</strong> Ошибка в незавершённом вводе ордеров стоит настоящих денег.</li></ul><p>Если вы всё же пользуетесь им — берите аккаунт, который не жалко потерять, и сначала изучите поведение кликов на минимальном размере ордера.</p><p>Если вы пришли в Sentaro ради мониторинга, этот инструмент вам вообще не нужен. Все остальные инструменты читают только публичные данные, никогда не запрашивают ключи и не могут торговать.</p></div>',5)),e(a,{src:"terminal",alt:"Окно Terminal с несколькими лестницами стакана",caption:"Окно Terminal — по лестнице на панель"}),t[1]||(t[1]=r('<p>Всё ниже описывает текущее поведение приложения. Поскольку это proof of concept, ожидайте изменений.</p><h2 id="настроика" tabindex="-1">Настройка <a class="header-anchor" href="#настроика" aria-label="Permalink to &quot;Настройка&quot;">​</a></h2><p>Откройте вкладку <strong>Terminal</strong> в главном окне. Настройки сгруппированы в сворачиваемые секции; начните с <strong>Exchange API keys</strong>.</p><h3 id="exchange-api-keys" tabindex="-1">Exchange API keys <a class="header-anchor" href="#exchange-api-keys" aria-label="Permalink to &quot;Exchange API keys&quot;">​</a></h3><p>По одному набору ключей на биржу. Каждый хранится в <strong>хранилище учётных данных ОС</strong> (Windows Credential Manager), никогда в файле настроек Sentaro, и используется только окном терминала.</p><h4 id="hyperliquid" tabindex="-1">Hyperliquid <a class="header-anchor" href="#hyperliquid" aria-label="Permalink to &quot;Hyperliquid&quot;">​</a></h4><p>Hyperliquid подписывает нативно и требует двух полей:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Что это</th></tr></thead><tbody><tr><td><strong>Private key</strong></td><td>Приватный ключ API-кошелька — <code>0x…</code>, 64 шестнадцатеричных символа</td></tr><tr><td><strong>Account address</strong></td><td><code>0x…</code> — адрес вашего основного аккаунта или хранилища (vault)</td></tr></tbody></table><p>Подсказка самого приложения: <em>приватный ключ API-кошелька (Hyperliquid → API). Укажите адрес основного аккаунта или хранилища, если ключ принадлежит агентскому кошельку.</em></p><p>Для отображения хранятся только последние 4 символа ключа. Адрес не является секретом, поэтому при редактировании он подставляется автоматически; ключ — никогда.</p><h4 id="binance" tabindex="-1">Binance <a class="header-anchor" href="#binance" aria-label="Permalink to &quot;Binance&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Поле</th><th>Что это</th></tr></thead><tbody><tr><td><strong>API key</strong></td><td>Ваш API-ключ Binance</td></tr><tr><td><strong>API secret</strong></td><td>Его секрет</td></tr></tbody></table><p>Подсказка приложения: <em>нужны «Enable Futures» и «Enable Spot &amp; Margin Trading». <strong>Никогда не включайте вывод средств.</strong></em></p><h4 id="bybit" tabindex="-1">Bybit <a class="header-anchor" href="#bybit" aria-label="Permalink to &quot;Bybit&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Поле</th><th>Что это</th></tr></thead><tbody><tr><td><strong>API key</strong></td><td>Ваш API-ключ Bybit</td></tr><tr><td><strong>API secret</strong></td><td>Его секрет</td></tr></tbody></table><p>Подсказка приложения: <em>ключ единого аккаунта с разрешением «Trade». <strong>Никогда не включайте вывод средств.</strong></em></p><div class="warning custom-block"><p class="custom-block-title">Никогда не включайте разрешение на вывод средств</p><p>Terminal нужна только торговля. API-ключ с правом вывода превращает любую ошибку, утечку файла настроек или компрометацию вашего компьютера в опустошённый аккаунт, а не в неудачную сделку.</p><p>Sentaro никогда не запрашивает разрешение на вывод и не имеет функции, которая бы его использовала.</p></div><h4 id="test" tabindex="-1">Test <a class="header-anchor" href="#test" aria-label="Permalink to &quot;Test&quot;">​</a></h4><p>У ключей Binance и Bybit есть кнопка <strong>Test</strong> (⟳). Ею стоит воспользоваться — это не проверка формата. Она передаёт ключ в рабочий процесс и выполняет реальный аутентифицированный запрос баланса, так что неверный ключ, отсутствие разрешения на торговлю или сбитые системные часы обнаруживаются здесь, а не в момент попытки торговать.</p><p>Каждая биржа отчитывается отдельной строкой, потому что один ключ может быть включён для фьючерсов, но не для спота.</p><h4 id="удаление-ключа" tabindex="-1">Удаление ключа <a class="header-anchor" href="#удаление-ключа" aria-label="Permalink to &quot;Удаление ключа&quot;">​</a></h4><p>Кнопка <strong>✕</strong> удаляет ключ из хранилища учётных данных ОС и убирает его из рабочего процесса, который мог уже его держать, так что удалённый ключ не продолжит работать до следующей перезагрузки.</p><div class="info custom-block"><p class="custom-block-title">Обновление со старой сборки</p><p>Предыдущие версии хранили до пяти именованных аккаунтов Hyperliquid с выбором активного. Это свелось к одному набору ключей на биржу, описанному выше.</p><p>При первом запуске ключ и адрес активного аккаунта переносятся автоматически. Ключи остальных аккаунтов <strong>не удаляются</strong> — они остаются в хранилище учётных данных ОС под старыми идентификаторами, недоступные из интерфейса, но восстанавливаемые вручную. Их идентификаторы один раз записываются в лог приложения во время миграции.</p></div>',23)),e(a,{src:"terminal-settings",alt:"Настройки размера ордера, ленты сделок и клавиш Terminal",caption:"Настройки Terminal — размер ордера, лента, клавиши"}),t[2]||(t[2]=r('<h3 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;Order&quot;">​</a></h3><h4 id="order-size-usd" tabindex="-1">Order size (USD) <a class="header-anchor" href="#order-size-usd" aria-label="Permalink to &quot;Order size (USD)&quot;">​</a></h4><p>Пять редактируемых пресетов номинального размера в долларах, который выставляется за клик. По умолчанию: <code>$11</code>, <code>$50</code>, <code>$500</code>, <code>$1000</code>, <code>$4000</code>.</p><p>Нажмите на пресет, чтобы выбрать его и изменить значение на месте. Выбранный пресет — это размер, который использует каждый клик; пресеты также выбираются с клавиатуры — см. <a href="#клавиши">Клавиши</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Активный пресет действует на каждый клик по лестнице. Поменяв его, вы меняете размер следующего ордера — проверяйте, какой пресет активен, прежде чем кликать.</p></div><h3 id="trade-tape" tabindex="-1">Trade tape <a class="header-anchor" href="#trade-tape" aria-label="Permalink to &quot;Trade tape&quot;">​</a></h3><h4 id="tape-style" tabindex="-1">Tape style <a class="header-anchor" href="#tape-style" aria-label="Permalink to &quot;Tape style&quot;">​</a></h4><p>Как принты сделок располагаются на ленте.</p><table tabindex="0"><thead><tr><th>Вариант</th><th>Поведение</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>По одному блоку на сделку — линия движется, только когда печатается новая сделка.</td></tr><tr><td><strong>Continuous</strong></td><td>Равномерные ячейки, но вся линия движется непрерывно.</td></tr><tr><td><strong>Overlap</strong></td><td>Каждая сделка стоит на своём реальном времени, так что сделки накладываются.</td></tr></tbody></table><h4 id="tape-speed" tabindex="-1">Tape speed <a class="header-anchor" href="#tape-speed" aria-label="Permalink to &quot;Tape speed&quot;">​</a></h4><p>За сколько линия сделок уходит из видимости. Диапазон <strong>от 1 до 15 секунд</strong>, по умолчанию 7.</p><p>Показывается только для стилей <strong>Continuous</strong> и <strong>Overlap</strong> — стиль Default движется по принтам, а не по времени, так что скорость к нему не применяется.</p><h2 id="торговля" tabindex="-1">Торговля <a class="header-anchor" href="#торговля" aria-label="Permalink to &quot;Торговля&quot;">​</a></h2><h3 id="выбор-площадки" tabindex="-1">Выбор площадки <a class="header-anchor" href="#выбор-площадки" aria-label="Permalink to &quot;Выбор площадки&quot;">​</a></h3><p>Площадка задаётся <strong>для каждой панели отдельно</strong>, кнопкой площадки в заголовке панели. Можно держать несколько панелей на разных площадках одновременно.</p><p>Переключение площадки с сохранением текущей монеты подставляет пару к USDT этой площадки. Если же выбрать рынок из поиска, переносится его настоящий символ, так что пары без USDT — вроде <code>ETH/BTC</code> или <code>SOL/USDC</code> — работают, а не переписываются молча на USDT-пару.</p><h3 id="торговля-кликом" tabindex="-1">Торговля кликом <a class="header-anchor" href="#торговля-кликом" aria-label="Permalink to &quot;Торговля кликом&quot;">​</a></h3><p>Лестница цен и есть ввод ордеров. Куда вы кликаете и какой кнопкой мыши — определяет и сторону, и тип ордера:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Положение строки</th><th>Результат</th></tr></thead><tbody><tr><td><strong>Левый клик</strong></td><td>На стороне asks (выше спреда)</td><td><strong>Рыночная покупка</strong></td></tr><tr><td><strong>Левый клик</strong></td><td>На стороне bids или в спреде</td><td><strong>Лимитная покупка</strong> по этой цене</td></tr><tr><td><strong>Правый клик</strong></td><td>На стороне bids (ниже спреда)</td><td><strong>Рыночная продажа</strong></td></tr><tr><td><strong>Правый клик</strong></td><td>На стороне asks или в спреде</td><td><strong>Лимитная продажа</strong> по этой цене</td></tr></tbody></table><p>Коротко: <strong>левый клик покупает, правый продаёт.</strong> Клик <em>через</em> спред — покупка в asks или продажа в bids — пересекает стакан и исполняется сразу как рыночный ордер. Клик на своей стороне оставляет лимитный ордер.</p><p>Рыночные ордера отправляются как immediate-or-cancel и проходят через противоположную сторону стакана.</p><p>Ордера срабатывают по клику без подтверждения. Повторные клики в течение 120 мс игнорируются — это спасает от случайного двойного срабатывания, но не мешает сознательному второму клику.</p><p>Только что выставленный ордер сразу рисуется на лестнице как <strong>ghost order</strong>, ещё до подтверждения биржей, чтобы вы видели, что отправили. Ошибки появляются всплывающим сообщением в окне.</p><h3 id="sl-tp" tabindex="-1">SL / TP <a class="header-anchor" href="#sl-tp" aria-label="Permalink to &quot;SL / TP&quot;">​</a></h3><p>Удерживайте клавишу <strong>Place SL / TP at row</strong> (по умолчанию <kbd>A</kbd>) и нажмите на строку лестницы, чтобы поставить стоп-лосс или тейк-профит по этой цене.</p><p>У существующих меток SL/TP есть ручка на боковой полосе, за которую их можно тянуть. При отпускании триггер переставляется на строку под курсором — сначала ставится новый, потом отменяется старый. Перетаскивание триггера через цену входа автоматически <strong>меняет SL ↔ TP</strong>, чтобы условие триггера оставалось корректным.</p><h3 id="триггерныи-вход" tabindex="-1">Триггерный вход <a class="header-anchor" href="#триггерныи-вход" aria-label="Permalink to &quot;Триггерный вход&quot;">​</a></h3><p>Удерживайте клавишу <strong>Arm trigger entry at row</strong> (по умолчанию <kbd>S</kbd>) и нажмите на строку лестницы, чтобы взвести вход, который сработает, когда цена его достигнет. Левый клик взводит покупку, правый — продажу.</p><h2 id="клавиши" tabindex="-1">Клавиши <a class="header-anchor" href="#клавиши" aria-label="Permalink to &quot;Клавиши&quot;">​</a></h2><p>Каждое сокращение ниже можно переназначить: откройте секцию <strong>Keybinds</strong>, нажмите кнопку клавиши и нажмите новую. <kbd>Esc</kbd> отменяет. Кнопка <strong>Reset</strong> возвращает все значения по умолчанию.</p><p>Привязки хранятся как физические позиции клавиш, так что они переживают смену раскладки клавиатуры.</p><h3 id="торговые-клавиши" tabindex="-1">Торговые клавиши <a class="header-anchor" href="#торговые-клавиши" aria-label="Permalink to &quot;Торговые клавиши&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Действие</th><th>По умолчанию</th></tr></thead><tbody><tr><td>Отменить все ордера</td><td><kbd>Space</kbd></td></tr><tr><td>Закрыть позицию (по рынку)</td><td><kbd>W</kbd></td></tr><tr><td>Развернуть позицию</td><td><kbd>Tab</kbd></td></tr><tr><td>Поиск тикера</td><td><kbd>F</kbd></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Отмена всех ордеров, закрытие и разворот позиции действуют мгновенно на активном наборе ключей, без какого-либо подтверждения.</p></div><h3 id="размер-ордера" tabindex="-1">Размер ордера <a class="header-anchor" href="#размер-ордера" aria-label="Permalink to &quot;Размер ордера&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Действие</th><th>По умолчанию</th></tr></thead><tbody><tr><td>Выбрать пресет 1–5</td><td><kbd>1</kbd> … <kbd>5</kbd></td></tr></tbody></table><h3 id="лестница" tabindex="-1">Лестница <a class="header-anchor" href="#лестница" aria-label="Permalink to &quot;Лестница&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Действие</th><th>По умолчанию</th></tr></thead><tbody><tr><td>Отцентрировать на best bid/ask</td><td><kbd>Shift</kbd> (левый)</td></tr><tr><td>Больший шаг цены</td><td><kbd>=</kbd></td></tr><tr><td>Меньший шаг цены</td><td><kbd>-</kbd></td></tr><tr><td>Изменить шаг цены</td><td><kbd>R</kbd> + прокрутка</td></tr><tr><td>Изменить границу полосы объёма</td><td><kbd>D</kbd> + прокрутка</td></tr><tr><td>Поставить SL / TP на строке</td><td><kbd>A</kbd> + клик</td></tr><tr><td>Взвести триггерный вход</td><td><kbd>S</kbd> + клик / правый клик</td></tr></tbody></table><p>Сокращения для рисования на графиках — луч, линия, магнит — <strong>не</strong> настраиваются здесь. Они во вкладке Home; см. <a href="/manual/ru/customize/chart-colors.html">Графики и рисование</a>.</p><h2 id="внешнии-вид" tabindex="-1">Внешний вид <a class="header-anchor" href="#внешнии-вид" aria-label="Permalink to &quot;Внешний вид&quot;">​</a></h2><p>Секция <strong>Appearance</strong> меняет вид лестницы. Кнопка <strong>Reset</strong> возвращает все значения на этой странице к значениям по умолчанию.</p><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Настройка</th><th>Что делает</th><th>Диапазон</th><th>По умолчанию</th></tr></thead><tbody><tr><td><strong>Text size</strong></td><td>Размер шрифта строки лестницы</td><td>9–18px</td><td>12px</td></tr><tr><td><strong>Row height</strong></td><td>Высота строки лестницы</td><td>8–20px</td><td>12px</td></tr><tr><td><strong>Big-volume threshold</strong></td><td>Заполнение полосы в %, после которого включается цвет «Volume big»</td><td>10–95%, шаг 5</td><td>60%</td></tr></tbody></table><p>Полоса глубины с заполнением 100% всегда использует цвет <strong>Volume full</strong>, независимо от этого порога.</p><h3 id="цвета" tabindex="-1">Цвета <a class="header-anchor" href="#цвета" aria-label="Permalink to &quot;Цвета&quot;">​</a></h3><p><strong>Background</strong> — один цвет фона стакана (по умолчанию <code>#181818</code>). Свою непрозрачность он хранит внутри hex, как и остальное приложение.</p><p>Остальное сгруппировано, и каждая запись хранит цвет и непрозрачность <strong>двумя отдельными значениями</strong> — именно поэтому эта панель, единственная в Sentaro, показывает процент рядом с каждой записью:</p><table tabindex="0"><thead><tr><th>Группа</th><th>Записи</th></tr></thead><tbody><tr><td><strong>Order book</strong></td><td>Bid, Ask, Best bid, Best ask, Price</td></tr><tr><td><strong>Volume bars</strong></td><td>Volume bar, Volume big, Volume full</td></tr><tr><td><strong>Position &amp; orders</strong></td><td>Placed order, Stop-loss, Take-profit, Position +PnL, Position −PnL</td></tr><tr><td><strong>Trade tape</strong></td><td>Tape buy, Tape sell</td></tr><tr><td><strong>General</strong></td><td>Text, Row hover</td></tr></tbody></table><p>Три цвета полос объёма образуют прогрессию: полоса использует <strong>Volume bar</strong> ниже порога большого объёма, <strong>Volume big</strong> выше него и <strong>Volume full</strong>, когда заполняет строку целиком. Три разных цвета делают относительную глубину понятной с первого взгляда.</p><p><strong>Position +PnL</strong> и <strong>Position −PnL</strong> заливают полосу позиции в зависимости от того, в прибыли она сейчас или в убытке.</p><h2 id="настроики-для-каждого-тикера" tabindex="-1">Настройки для каждого тикера <a class="header-anchor" href="#настроики-для-каждого-тикера" aria-label="Permalink to &quot;Настройки для каждого тикера&quot;">​</a></h2><p>Шаг цены и граница полосы объёма хранятся <strong>для каждой монеты отдельно</strong>, а не глобально — настроив лестницу для BTC, вы не меняете вид ETH. Это задаётся из окна клавишами лестницы выше, а не из вкладки настроек.</p><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/getting-started.html">Начало работы</a> — остальной Sentaro, которому не нужны ключи и который не может торговать</li></ul>',54))])}const k=d(i,[["render",l]]);export{m as __pageData,k as default};
